var pred = List.filled(3, 0), lastInterval = -1;
final ri = g.restart == 0 ? g.mx * g.my : g.restart;
for (final b in e.blocks) {
  final j = b.mcu ~/ ri;
  if (j != lastInterval) {
    pred = List.filled(3, 0);
    lastInterval = j;
  }
  b.diff = b.z[0] - pred[b.k];
  pred[b.k] = b.z[0];
